{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 5,
      "reason": "電子郵件完整地完成任務：邀請朋友來台灣（\"Would you like to come and stay with me in Taiwan next summer?\"）並建議可一起做的活動，語氣也適合朋友間的非正式信件。"
    },
    {
      "id": "organization",
      "score": 5,
      "reason": "段落分明且有清楚順序：開頭問候、提出邀請、行程計劃、住宿安排與結尾聯絡方式（例如\"I've already sketched out a rough plan.\"、\"Let me know what dates might work for you.\"）。"
    },
    {
      "id": "vocabulary",
      "score": 5,
      "reason": "詞彙自然且貼切，如描述食物和地點的用語（\"breakfast shops serving soy milk and egg pancakes\", \"night markets\"、\"Pacific views\"）準確且多樣。"
    },
    {
      "id": "grammar",
      "score": 5,
      "reason": "句子結構正確，時態一致，沒有明顯語法錯誤（例如\"I'd like to take you down the east coast by train\"、\"my mother has already promised\"）。"
    }
  ],
  "issues": [
    {
      "quote": "I've already sketched out a rough plan.",
      "type": "word-choice",
      "why": "\"sketched out a rough plan\" 有點重複（sketched out 和 rough 都表達草略），對話語氣可以更簡潔自然。",
      "suggestion": "I've put together a rough plan."
    },
    {
      "quote": "from breakfast shops serving soy milk and egg pancakes to the night markets that stay busy until midnight.",
      "type": "punctuation",
      "why": "這個長片語有點長，插入的細節使句子讀起來重，使用逗號或分號可以改善可讀性。",
      "suggestion": "from breakfast shops serving soy milk and egg pancakes, to night markets busy until midnight."
    },
    {
      "quote": "You're welcome to stay with my family, and my mother has already promised to teach you how to make dumplings.",
      "type": "cohesion",
      "why": "句子資訊豐富但略長，可分成兩句以強調兩個不同的邀請（住宿與學做餃子）。",
      "suggestion": "You're welcome to stay with my family. My mother has promised to teach you how to make dumplings."
    }
  ],
  "more": [
    {
      "quote": "Would you like to come and stay with me in Taiwan next summer?",
      "type": "tone",
      "why": "這句很自然；若想更禮貌或彈性可加入更具體的日期或長度建議。",
      "suggestion": "Would you like to come and stay with me in Taiwan next summer for a week or two?"
    },
    {
      "quote": "Then I'd like to take you down the east coast by train, where the Pacific views are spectacular, and finish with a couple of lazy days in Tainan, the city where I grew up.",
      "type": "sentence",
      "why": "這是良好的描述句，但包含多個想法，可考慮分句以強調每個活動。",
      "suggestion": "Then I'd like to take you down the east coast by train to enjoy the Pacific views. We could finish with a couple of lazy days in Tainan, the city where I grew up."
    }
  ],
  "strengths": [
    {
      "quote": "We could spend a few days exploring Taipei's food scene",
      "why": "清楚說明計劃並用具體活動吸引讀者，讓邀請更有吸引力。"
    },
    {
      "quote": "my mother has already promised to teach you how to make dumplings.",
      "why": "個人化的細節增加親切感，讓邀請顯得真誠且有家庭氛圍。"
    }
  ],
  "summary": "你的信件結構清楚、語氣自然，內容具體且富吸引力。接下來可注意長句的標點與分句，把長資訊拆成較短的句子，並在需要時加入更具體的日期或停留時間建議，讓對方更容易回覆。"
}
